create table mailboxes_state(channel_id int primary key references channels,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,uid_validity text,last_uid bigint not null default 0,synced_at timestamptz,error text,state text not null default 'configured');
create table mail_receipts(id bigserial primary key,tenant_id int not null default nullif(current_setting('app.tenant',true),'')::int references tenants on delete cascade,channel_id int not null references channels,uid_validity text not null,uid bigint not null,ext_id text not null,rfc_message_id text,subject text,imported boolean not null default false,unique(channel_id,uid_validity,uid),unique(tenant_id,ext_id));
do $$declare r record;begin for r in select * from(values('mailboxes_state','channels,channel_id'),('mail_receipts','channels,channel_id')) v(t,refs) loop execute format('alter table %I enable row level security',r.t);execute format('alter table %I force row level security',r.t);execute format('create policy tenant_iso on %I using(tenant_id=nullif(current_setting(''app.tenant'',true),'''')::int) with check(tenant_id=nullif(current_setting(''app.tenant'',true),'''')::int)',r.t);execute format('create trigger fk_guard before insert or update on %I for each row execute function fk_guard(%s)',r.t,(select string_agg(quote_literal(x),',') from unnest(string_to_array(r.refs,',')) x));end loop;end $$;
alter table mailboxes_state add column lease_token text,add column lease_until timestamptz;
